-- Agent Gateway (#14): revocable Agent Tokens authenticate an external Agent
-- Runner to the app's MCP route. The random secret is generated by the app,
-- shown once, and only its SHA-256 hash reaches this table.
create table public.agent_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  token_hash text not null unique,
  label text not null,
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  constraint agent_tokens_label_not_blank check (btrim(label) <> ''),
  constraint agent_tokens_hash_not_blank check (btrim(token_hash) <> '')
);

comment on table public.agent_tokens is
  'Revocable credentials for an Agent Runner. token_hash is a SHA-256 hash of the one-time secret; raw Agent Tokens are never stored. user_id is resolved server-side before every MCP tool call and establishes the RLS subject for that request.';
comment on column public.agent_tokens.token_hash is
  'SHA-256 hex digest of an Agent Token. Never store or return its raw secret.';
comment on column public.agent_tokens.revoked_at is
  'Set when a user revokes this Agent Token. Gateway authentication rejects it immediately.';

create index agent_tokens_active_hash_idx
  on public.agent_tokens (token_hash)
  where revoked_at is null;
create index agent_tokens_user_created_at_idx
  on public.agent_tokens (user_id, created_at desc);

select public.apply_deny_all_rls('public.agent_tokens');

create policy "agent_tokens_select_own"
  on public.agent_tokens for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy "agent_tokens_insert_own"
  on public.agent_tokens for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "agent_tokens_update_own"
  on public.agent_tokens for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Existing Pantry summary predates the security-invoker convention. The
-- Agent Gateway reads it while impersonating a token owner, so it must never
-- execute with the view owner's RLS-bypassing privileges.
alter view public.pantry_summary set (security_invoker = on);
